=== src/service/SettlementService.java ===
     1	package service;
     2	
     3	import domain.DailyLine;
     4	import domain.Partner;
     5	import domain.Transaction;
     6	import infra.DataFiles;
     7	import util.Money;
     8	
     9	import java.time.LocalDate;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.Map;
    13	import java.util.TreeMap;
    14	
    15	/** Builds per-partner daily settlement lines from the transaction feed. */
    16	public class SettlementService {
    17	    private final DataFiles data;
    18	    private final RateService rates;
    19	    private final BusinessDateResolver dates;
    20	
    21	    public SettlementService(DataFiles data, RateService rates, BusinessDateResolver dates) {
    22	        this.data = data;
    23	        this.rates = rates;
    24	        this.dates = dates;
    25	    }
    26	
    27	    public List<DailyLine> settle(LocalDate from, LocalDate to) {
    28	        Map<String, long[]> acc = new TreeMap<>(); // key "date|partner" -> {count, grossKrw}
    29	        for (Transaction t : data.transactions()) {
    30	            LocalDate d = dates.dateOf(t.approvedAt());
    31	            if (d.isBefore(from) || d.isAfter(to)) continue;
    32	            Partner p = data.partner(t.partnerId()).orElse(null);
    33	            if (p == null || !p.active()) continue;
    34	            long krw = convert(t, d);
    35	            long[] a = acc.computeIfAbsent(d + "|" + p.id(), k -> new long[2]);
    36	            a[0]++;
    37	            a[1] += krw;
    38	        }
    39	        List<DailyLine> out = new ArrayList<>();
    40	        for (var e : acc.entrySet()) {
    41	            String[] k = e.getKey().split("\\|");
    42	            Partner p = data.partner(k[1]).orElseThrow();
    43	            long gross = e.getValue()[1];
    44	            out.add(new DailyLine(LocalDate.parse(k[0]), p.id(), (int) e.getValue()[0], gross,
    45	                    Money.fee(gross, p.feeBps())));
    46	        }
    47	        return out;
    48	    }
    49	
    50	    private long convert(Transaction t, LocalDate businessDate) {
    51	        var rate = rates.settlementRate(t.currency(), businessDate);
    52	        return Money.toKrw(t.signedAmount(), rate, CurrencyPairs.unitOf(t.currency()));
    53	    }
    54	}
=== src/service/ReconcileService.java ===
     1	package service;
     2	
     3	import domain.DailyLine;
     4	import domain.StatementRow;
     5	
     6	import java.time.LocalDate;
     7	import java.util.ArrayList;
     8	import java.util.HashMap;
     9	import java.util.List;
    10	import java.util.Map;
    11	
    12	/** Compares our daily lines with the partners' statements. */
    13	public class ReconcileService {
    14	
    15	    /** Difference between our settlement and the partner's statement for a date/partner. */
    16	    public record Mismatch(LocalDate date, String partnerId, String field, long ours, long theirs) {
    17	        public long diff() { return ours - theirs; }
    18	    }
    19	
    20	    public List<Mismatch> compare(List<DailyLine> ours, List<StatementRow> theirs) {
    21	        Map<String, DailyLine> mine = new HashMap<>();
    22	        for (DailyLine l : ours) mine.put(key(l.date(), l.partnerId()), l);
    23	        List<Mismatch> out = new ArrayList<>();
    24	        for (StatementRow r : theirs) {
    25	            DailyLine l = mine.remove(key(r.date(), r.partnerId()));
    26	            if (l == null) {
    27	                out.add(new Mismatch(r.date(), r.partnerId(), "missing", 0, r.grossKrw()));
    28	                continue;
    29	            }
    30	            if (l.count() != r.count()) out.add(new Mismatch(r.date(), r.partnerId(), "count", l.count(), r.count()));
    31	            if (l.grossKrw() != r.grossKrw()) out.add(new Mismatch(r.date(), r.partnerId(), "gross", l.grossKrw(), r.grossKrw()));
    32	        }
    33	        for (DailyLine l : mine.values()) {
    34	            out.add(new Mismatch(l.date(), l.partnerId(), "unexpected", l.grossKrw(), 0));
    35	        }
    36	        out.sort((a, b) -> a.date().equals(b.date()) ? a.partnerId().compareTo(b.partnerId()) : a.date().compareTo(b.date()));
    37	        return out;
    38	    }
    39	
    40	    private static String key(LocalDate d, String partner) {
    41	        return d + "|" + partner;
    42	    }
    43	}
=== src/api/SettlementApi.java ===
     1	package api;
     2	
     3	import config.AppConfig;
     4	import domain.DailyLine;
     5	import domain.FxQuote;
     6	import service.ReconcileService.Mismatch;
     7	import infra.FxqClient;
     8	import infra.DataFiles;
     9	import service.BusinessDateResolver;
    10	import service.RateBoardService;
    11	import service.RateService;
    12	import service.ReconcileService;
    13	import service.SettlementService;
    14	
    15	import java.time.LocalDate;
    16	import java.util.List;
    17	
    18	/** Facade used by the batch CLI, the ops console and the app gateway. */
    19	public class SettlementApi {
    20	    private final SettlementService settlement;
    21	    private final ReconcileService reconcile = new ReconcileService();
    22	    private final RateBoardService board;
    23	    private final DataFiles data;
    24	
    25	    public SettlementApi(AppConfig cfg) {
    26	        FxqClient fxq = new FxqClient(cfg.fxqBin(), cfg.fxqTimeoutSeconds());
    27	        RateService rates = new RateService(fxq);
    28	        this.data = new DataFiles(cfg.dataDir());
    29	        this.settlement = new SettlementService(data, rates, new BusinessDateResolver(cfg.businessZone()));
    30	        this.board = new RateBoardService(rates, cfg.boardCurrencies());
    31	    }
    32	
    33	    public static SettlementApi fromDefaultConfig() {
    34	        return new SettlementApi(AppConfig.load());
    35	    }
    36	
    37	    public List<DailyLine> daily(LocalDate from, LocalDate to) {
    38	        return settlement.settle(from, to);
    39	    }
    40	
    41	    public String dailyReport(LocalDate from, LocalDate to) {
    42	        return ReportFormatter.daily(daily(from, to), data);
    43	    }
    44	
    45	    public List<Mismatch> reconcile(LocalDate from, LocalDate to) {
    46	        return reconcile.compare(daily(from, to), data.statements(from, to));
    47	    }
    48	
    49	    public String reconcileReport(LocalDate from, LocalDate to) {
    50	        return ReportFormatter.mismatches(reconcile(from, to));
    51	    }
    52	
    53	    public String exportCsv(LocalDate from, LocalDate to) {
    54	        return ReportFormatter.csv(daily(from, to));
    55	    }
    56	
    57	    public List<FxQuote> rateBoard(LocalDate date) {
    58	        return board.board(date);
    59	    }
    60	
    61	    public String rateBoardText(LocalDate date) {
    62	        return ReportFormatter.board(date, rateBoard(date));
    63	    }
    64	}
=== src/api/Main.java ===
     1	package api;
     2	
     3	import java.time.LocalDate;
     4	
     5	/**
     6	 * Ops CLI.
     7	 *   report    FROM TO   daily settlement per partner
     8	 *   reconcile FROM TO   compare with partner statements
     9	 *   export    FROM TO   CSV for accounting
    10	 *   board     DATE      exchange rate board
    11	 */
    12	public final class Main {
    13	    private Main() {}
    14	
    15	    public static void main(String[] args) {
    16	        if (args.length < 2) {
    17	            System.err.println("usage: report|reconcile|export FROM TO | board DATE");
    18	            System.exit(64);
    19	        }
    20	        SettlementApi api = SettlementApi.fromDefaultConfig();
    21	        LocalDate a = LocalDate.parse(args[1]);
    22	        LocalDate b = args.length > 2 ? LocalDate.parse(args[2]) : a;
    23	        switch (args[0]) {
    24	            case "report" -> System.out.print(api.dailyReport(a, b));
    25	            case "reconcile" -> System.out.print(api.reconcileReport(a, b));
    26	            case "export" -> System.out.print(api.exportCsv(a, b));
    27	            case "board" -> System.out.print(api.rateBoardText(a));
    28	            default -> {
    29	                System.err.println("unknown command " + args[0]);
    30	                System.exit(64);
    31	            }
    32	        }
    33	    }
    34	}

