/** Raw stdout line for {@code fxq rate PAIR DATE} (vendor default source). */
public String rate(String pair, LocalDate date) {
    return rate(pair, date, null);
}

/** Raw stdout line for {@code fxq rate PAIR DATE --src N}; {@code source} null means the default. */
public String rate(String pair, LocalDate date, Integer source) {
    List<String> cmd = new ArrayList<>();
    cmd.add(bin.toString());
    cmd.add("rate");
    cmd.add(pair);
    cmd.add(date.toString());
    if (source != null) {
        cmd.add("--src");
        cmd.add(source.toString());
    }
    return run(cmd);
}

/** Parses one quote line: {@code PAIR YYYY-MM-DD RATE [~N]}. A trailing {@code ~N} marks a carried-over value. */
public static FxQuote parse(String line) {
    String[] t = line.trim().split("\\s+");
    if (t.length < 3) {
        throw new IllegalArgumentException("unexpected quote line: " + line);
    }
    boolean lagged = t.length > 3 && t[3].startsWith("~");
    return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]), lagged);
}

