        return q.lagged() ? fetch(currency, date, SETTLEMENT_SOURCE).rate() : q.rate();
    }

    private FxQuote fetch(String currency, LocalDate date, Integer source) {
        String pair = CurrencyPairs.pairOf(currency);
        String key = pair + "@" + date + "@" + (source == null ? "default" : source);
        return cache.computeIfAbsent(key, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date, source));
        });
    }

